```yaml
name: Rule type param changes comment

on:
  pull_request:
    types:
      - opened
      - synchronize
      - reopened

jobs:
  rule-type-param-changes-comment:
    name: Rule type param changes comment
    runs-on: ubuntu-latest
    if: |
      github.repository == 'elastic/kibana' &&
      github.event.pull_request.draft == false &&
      (contains(github.event.pull_request.labels.*.name, 'Team:cloud-security-posture') || 
       contains(github.event.pull_request.labels.*.name, 'Team:contextual-security'))
    steps:
      - name: Comment on PR
        uses: actions/github-script@ed597411d8f924073f98dfc5c65a23a2325f34cd # v8.0.0
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const fs = require('fs');
            const path = require('path');

            // Read the CODEOWNERS file
            const codeownersPath = '.github/CODEOWNERS';
            const codeownersContent = fs.readFileSync(codeownersPath, 'utf8');

            // Check if the old team name exists in CODEOWNERS
            if (codeownersContent.includes('@kibana/cloud-security-posture')) {
              // Replace the old team name with the new one
              const updatedContent = codeownersContent.replace(/@kibana\/cloud-security-posture/g, '@kibana/contextual-security');

              // Write the updated content back to CODEOWNERS
              fs.writeFileSync(codeownersPath, updatedContent);

              // Create a comment on the PR
              await github.rest.issues.createComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: context.payload.pull_request.number,
                body: 'The GitHub team reference in `.github/CODEOWNERS` has been updated from `@kibana/cloud-security-posture` to `@kibana/contextual-security`. Please review the changes.'
              });
            }
